import{_ as o,l as n,o as e,c as s,v as t,p as l,x as r,d,i as p,S as I}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"NMI","description":"","frontmatter":{"title":"NMI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nmi.md","filePath":"cs/nmi.md","lastUpdated":1789023840000}'),c={name:"cs/nmi.md"};function h(E,a,m,M,N,_){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="nmi" tabindex="-1">NMI <a class="header-anchor" href="#nmi" aria-label="Permalink to &quot;NMI&quot;">​</a></h1><div class="epigraph"><p>不可屏蔽中断在普通 IRQ 已关闭时仍能进入；它几乎不能拿常规锁，也不能走可推迟的下半部。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Intel/AMD 与 RISC-V 特权手册对 NMI 的整理</footer></div><p><a href="/cs/irq-affinity">上一课</a>让可屏蔽设备 IRQ 可以绑核、可以推迟。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>里的普通中断能被状态位关掉。缺口是：看门狗、机器检查、某些调试事件必须在「已经关中断」的路径上仍能打断 CPU——<strong>NMI</strong>。本课只钉它与普通 IRQ 的差别，不写处理器勘误表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核关本地中断是为了保护与 ISR 共享的数据。若死循环发生在关中断区间，普通时钟 IRQ 进不来，调度器救不了。NMI 绕过屏蔽，进入另一套入口：不重入或极窄重入、栈往往是专用 NMI 栈，避免在已损坏的内核栈上再压帧。缺口不是新的亲和掩码，而是承认存在<strong>不能推迟、不能睡、几乎不能拿自旋锁</strong>的上下文——因为锁的持有者可能正是被 NMI 打断的那条路径。</p><p><span class="marginnote">NMI 处理程序里打印、分配、拿 <code>spinlock</code> 都可能死锁。实践是：碰 per-CPU 无锁状态、触发崩溃转储、或只置位留给稍后的可屏蔽路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件投递 NMI 向量。入口：切到 NMI 栈，保存最小状态，跑处理函数，退出时恢复屏蔽语义。看门狗：NMI 里检查「该核是否还在打卡」；若普通时钟长期未跑，判定锁死。本课不把 kdump 的全部协议写完。</p>',8)),(e(),l(I,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%99%AE%E9%80%9A%20IRQ%20%E5%8F%AF%E5%85%B3%22%5D%20--%3E%20STILL%5B%22NMI%20%E4%BB%8D%E5%8F%AF%E8%BF%9B%22%5D%0A%20%20STILL%20--%3E%20NMI%5B%22NMI%20%E6%A0%88%E4%B8%8E%E6%9E%81%E7%9F%AD%E5%A4%84%E7%90%86%22%5D%0A%20%20NMI%20--%3E%20LATER%5B%22%E8%87%B3%E5%A4%9A%E7%BD%AE%E4%BD%8D%2C%20%E7%95%99%E7%BB%99%E5%8F%AF%E5%B1%8F%E8%94%BD%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/interrupt-bottom-half">中断下半部</a>的纪律相反：NMI 没有标准下半部。想推迟，只能置标志，等下一次可屏蔽中断或调度点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NMI 把「关中断 = 原子」这句话限制成「对可屏蔽 IRQ 原子」。写内核的人必须假设 NMI 可以嵌在任何关中断区间。因此 per-CPU 统计若要在 NMI 里更新，要用 NMI 安全的原子或专用缓冲。这为后课内核抢占与 per-CPU 数据预告约束，本课不展开抢占计数。</p><p>不可用 NMI 来做普通设备完成通知：丢失与嵌套语义都太凶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SMM、机器检查异常的全部严重度分级写完，不讨论如何用 NMI 做隐蔽通道。也不把用户态「假 NMI」当对象：用户不能发真 NMI。</p><p>后课默认：存在不能屏蔽的入口。内核执行路径何时能被<strong>另一条内核线程</strong>抢走 CPU，下一课讲内核抢占。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NMI 绕过普通关中断；无标准下半部，几乎不能拿常规锁。</li><li>看门狗一类诊断依赖它；设备完成不要走它。</li><li>内核路径上的抢占是下一课。</li><li>出处：Bovet and Cesati；Love, <em>LKD</em>。</li></ul>',9))])}const A=o(c,[["render",h]]);export{f as __pageData,A as default};
